import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  /** The sheet's today (YYYY-MM-DD): every date-dependent decision and default uses it. */
  today: string;
}

// Who is signed in and which sheet is active. Every request to the server carries the signed-in
// name in the X-User header (see `headers()`); everything else in the app is kept per sheet.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The active sheet's today (YYYY-MM-DD); use it, never the browser's clock. */
  readonly today = signal<string | null>(null);
  /** Counts sheet loads, so a view re-reads the store even when the same id is loaded again. */
  readonly loads = signal(0);
  readonly signedIn = computed(() => this.user() !== null);

  signIn(name: string): boolean {
    const user = name.trim();
    if (!user) return false;
    this.user.set(user);
    this.sheetId.set(null);
    this.today.set(null);
    return true;
  }

  headers(): HttpHeaders {
    return new HttpHeaders({ 'X-User': this.user() ?? '' });
  }

  /** Load a sheet by id (starting it empty if never used); resolves false when refused. */
  async loadSheet(id: string): Promise<boolean> {
    const sheet = id.trim();
    if (!sheet || !this.user()) return false;
    try {
      const view = await firstValueFrom(
        this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(sheet)}/load`, null, {
          headers: this.headers(),
        }),
      );
      this.show(view);
      this.loads.update((n) => n + 1);
      return true;
    } catch {
      return false;
    }
  }

  /** Change the active sheet's today; resolves false when refused. */
  async setToday(date: string): Promise<boolean> {
    const sheet = this.sheetId();
    const today = date.trim();
    if (!sheet || !/^\d{4}-\d{2}-\d{2}$/.test(today)) return false;
    try {
      const view = await firstValueFrom(
        this.http.put<SheetView>(
          `/api/sheets/${encodeURIComponent(sheet)}/today`,
          { today },
          { headers: this.headers() },
        ),
      );
      if (this.sheetId() === view.id) this.show(view);
      return true;
    } catch {
      return false;
    }
  }

  private show(view: SheetView): void {
    this.sheetId.set(view.id);
    this.today.set(view.today);
  }
}
   *  their grade applies then. A claim settled
   *  at a rate keeps what was due on it then; one settled without a rate fixed nothing. */
  protected dueOf(claim: Claim): string {
    const due = claimDueCents(claim, this.rates(), this.grade());
    return due === null ? 'n/a' : money(due);
  }

  /** The name of the period whose dates contain the claim's date; empty when none does. */
  protected periodOf(claim: Claim): string {
    return periodOn(this.periods(), claim.date)?.name ?? '';
  }

  /** Open the claim's editor; only a DRAFT can be edited, so the edit of any other claim is refused with
   *  an error on the claim (an open claim is changed by voiding it and adding a new one). */
  protected edit(claim: Claim): void {
    this.clearRowError(claim.id);
    if (claim.status !== 'DRAFT') {
      if (this.editingId() === claim.id) this.reset();
      this.rowErrors.update((errors) => ({
        ...errors,
        [claim.id]: 'Only a draft claim can be edited; void it and add a new one instead.',
      }));
      return;
    }
    this.editingId.set(claim.id);
    this.amount.set(claim.amount);
    this.date.set(claim.date);
    this.note.set(claim.note);
    this.error.set(null);
  }

  /** Change the claim's status; a change its status does not allow, or a settle by the user who opened
   *  the claim, is refused with an error. */
  protected async act(claim: Claim, action: ClaimAction): Promise<void> {
    this.clearRowError(claim.id);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    try {
      const changed = await this.service.act(sheet, claim.id, action);
      if (this.session.sheetId() === sheet) this.saved.emit(changed);
    } catch (e) {
      if (this.session.sheetId() !== sheet) return;
      this.rowErrors.update((errors) => ({
        ...errors,
        [claim.id]: e instanceof HttpErrorResponse && e.status === 403
          ? 'You opened that claim, so another user must settle it.'
          : e instanceof HttpErrorResponse && e.status === 423
          ? 'That claim is dated in a closed period.'
          : `That claim cannot be ${action === 'open' ? 'opened' : action === 'settle' ? 'settled' : 'voided'} in its status.`,
      }));
    }
  }

  private clearRowError(id: number): void {
    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.amount.set('');
    this.date.set('');
    this.note.set('');
    this.error.set(null);
  }

  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const amount = this.amount().trim();
    if (!AMOUNT.test(amount)) {
      this.error.set('Type an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    const fields = { amount, date: this.date().trim() || null, note: this.note() };
    const id = this.editingId();
    this.submitting = true;
    try {
      const claim =
        id === null
          ? await this.service.add(sheet, this.personId(), fields)
          : await this.service.update(sheet, id, fields);
      if (this.session.sheetId() !== sheet) return;
      this.saved.emit(claim);
      this.reset();
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 423
          ? 'A claim dated in a closed period cannot be changed.'
          : id !== null && e instanceof HttpErrorResponse && e.status === 409
            ? 'Only a draft claim can be edited; void it and add a new one instead.'
          : id === null
            ? 'That claim could not be added.'
            : 'That claim could not be saved.',
      );
    } finally {
      this.submitting = false;
    }
  }
}

